#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <mma.h>
using namespace nvcuda;
#define BM 128
#define BN 128
#define BK 16         // shallow K tile: halves smem per CTA so 2 CTAs/SM fit (doubles occupancy)
#define BN 64          // narrower CTA N-tile: halves accumulators/B fragments per warp to cut register pressure
#define BNP (BN + 8)  // B smem row stride: 72 floats, padded so scalar B-fragment loads remain bank-conflict-free
#define WM 32         // warp tile M
#define WN 32         // warp tile N (32x32 warp tile; 4x2 warps still cover BM x BN)
